(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-585":{scenario:{company:"Ánh Dương Smart Assembly",supervisor:{name:"Lý Quốc Bảo",role:{vi:"Trưởng nhóm Robot & Thị giác máy",en:"Robotics & Machine Vision Lead"}},ref_code:"VIS-7304",title:{vi:"Đủ điểm ảnh. Đúng camera. Không tắt vùng an toàn.",en:"Enough pixels. Right camera. Never mute the safety zone."},brief:{vi:"Trạm VIS-7304 trong ô robot gắp vỏ nhôm cần phát hiện vết xước nhỏ nhất 0.2 mm. Trường nhìn ngang 160 mm (đã gồm dung sai vị trí ±5 mm), quy tắc đã duyệt: khuyết tật nhỏ nhất phủ tối thiểu 3 điểm ảnh. Bản thiết kế nháp tính sai số điểm ảnh và chọn camera chưa đạt. Đối chiếu với đặc tả kiểm tra, sửa số điểm ảnh ngang yêu cầu và camera, rồi lập báo cáo có căn cứ.",en:"Station VIS-7304 in an aluminium housing pick-and-place robot cell must detect scratches down to 0.2 mm. The horizontal field of view is 160 mm (including ±5 mm positioning tolerance), and the approved rule says the smallest defect must cover at least 3 pixels. The draft design miscalculates the pixel count and picks an inadequate camera. Check it against the inspection specification, correct the required horizontal pixels and the camera, then write an evidence-based report."},reference_title:{vi:"Đặc tả kiểm tra thị giác đã duyệt · VIS-7304",en:"Approved vision inspection specification · VIS-7304"},fields:[{id:"CAMERA",label:{vi:"Camera được chọn",en:"Selected camera"},initial:"CAM-2MP",expected:"CAM-5MP",choices:["CAM-2MP","CAM-5MP","CAM-12MP"],reference:"Danh mục camera đã thẩm định",hint:{vi:"Chọn camera nhỏ nhất có số điểm ảnh ngang không thấp hơn yêu cầu; quá dư làm tăng chi phí và thời gian xử lý.",en:"Choose the smallest camera whose horizontal pixels meet the requirement; oversizing adds cost and processing time."}},{id:"PX_REQ",label:{vi:"Số điểm ảnh ngang yêu cầu (px)",en:"Required horizontal pixels (px)"},initial:"800",expected:"2400",reference:"Bảng tính độ phân giải không gian",ref_value:{vi:"Trường nhìn ngang 160 mm; khuyết tật nhỏ nhất 0.2 mm; tối thiểu 3 điểm ảnh trên khuyết tật",en:"Horizontal FOV 160 mm; smallest defect 0.2 mm; at least 3 pixels across the defect"},hint:{vi:"Một điểm ảnh cho mỗi khuyết tật là không đủ để phát hiện tin cậy; áp đúng số điểm ảnh tối thiểu.",en:"One pixel per defect is not enough for reliable detection; apply the minimum pixel count."}}],sop32:{vi:"Số điểm ảnh ngang yêu cầu = trường nhìn / (kích thước khuyết tật nhỏ nhất / số điểm ảnh tối thiểu trên khuyết tật); chọn camera nhỏ nhất có số điểm ảnh ngang ≥ yêu cầu.",en:"Required horizontal pixels = field of view / (smallest defect size / minimum pixels per defect); choose the smallest camera with horizontal pixels ≥ the requirement."},context:{label:"VISION CONFIG / VIS-7304",metrics:[{label:{vi:"Trường nhìn ngang",en:"Horizontal FOV"},value:"160 mm"},{label:{vi:"Khuyết tật nhỏ nhất",en:"Smallest defect"},value:"0.2 mm"},{label:{vi:"Tỷ lệ phát hiện thử",en:"Trial detection rate"},value:"71%"}]},terminal:{system:"vision-cfg",settable:["CAMERA","PX_REQ"],commands:[{cmd:"status",out:{vi:"Trạm VIS-7304: robot 6 trục gắp vỏ nhôm, đèn vòm khuếch tán; cấu hình nháp CAMERA=CAM-2MP, PX_REQ=800",en:"Station VIS-7304: 6-axis robot picks aluminium housings, diffuse dome light; draft CAMERA=CAM-2MP, PX_REQ=800"}},{cmd:"cat inspection_spec.txt",out:{vi:"Vết xước nhỏ nhất 0.2 mm; quy tắc nhà máy: khuyết tật nhỏ nhất phải phủ tối thiểu 3 điểm ảnh",en:"Smallest scratch 0.2 mm; plant rule: smallest defect must cover at least 3 pixels"}},{cmd:"cat fov.txt",out:{vi:"Chiều dài chi tiết 150 mm, dung sai vị trí ±5 mm; trường nhìn ngang 160 mm",en:"Part length 150 mm, positioning tolerance ±5 mm; horizontal FOV 160 mm"}},{cmd:"cat camera_list.txt",out:{vi:"CAM-2MP 1600 x 1200; CAM-5MP 2448 x 2048; CAM-12MP 4096 x 3000; cùng ngàm ống kính và giao tiếp",en:"CAM-2MP 1600 x 1200; CAM-5MP 2448 x 2048; CAM-12MP 4096 x 3000; same lens mount and interface"}},{cmd:"grab test",out:{vi:"Ảnh thử với CAM-2MP: 0.1 mm/px, vết xước 0.2 mm chỉ phủ 2 điểm ảnh, tỷ lệ phát hiện 71%",en:"Test image with CAM-2MP: 0.1 mm/px, 0.2 mm scratch covers only 2 pixels, detection rate 71%"}}]},crisis:{vi:"Quản lý dự án nhắn: “Khách đến nghiệm thu chiều nay, robot chạy chậm vì cảm biến quét vùng an toàn cứ dừng máy. Tắt cảm biến đi cho robot chạy tốc độ đầy đủ khi demo.”",en:"The project manager messages: “The client comes for acceptance this afternoon and the robot is slow because the safety laser scanner keeps stopping it. Mute the scanner so the robot runs at full speed for the demo.”"},options:{safe:{vi:"Từ chối tắt cảm biến an toàn; kiểm tra lại cấu hình vùng quét theo đánh giá rủi ro, báo trưởng nhóm và đề nghị dời phần demo tốc độ cao nếu chưa đạt.",en:"Refuse to mute the safety scanner; recheck the zone configuration against the risk assessment, inform the lead and propose postponing the high-speed demo if it is not ready."},shortcut:{vi:"Tắt cảm biến quét trong buổi demo rồi bật lại khi khách về.",en:"Mute the scanner during the demo and turn it back on after the client leaves."},wait:{vi:"Không trả lời và để quản lý dự án tự xử lý với khách.",en:"Do not reply and let the project manager handle the client."}},questions:{vi:["Vì sao cần 2400 điểm ảnh ngang và camera CAM-5MP? Độ phân giải mm/px thực tế sau khi đổi camera là bao nhiêu?","Vì sao không được tắt cảm biến vùng an toàn dù chỉ để demo, và bạn xử lý dừng máy phiền toái thế nào cho đúng?"],en:["Why are 2400 horizontal pixels and the CAM-5MP needed? What is the actual mm/px resolution after the change?","Why must the safety scanner never be muted even for a demo, and how should nuisance stops be handled properly?"]},hints:{vi:["Đặt cấu hình nháp cạnh đặc tả kiểm tra và đọc lại quy tắc số điểm ảnh tối thiểu.","Áp dụng SOP mục 3.2: đổi kích thước khuyết tật ra kích thước mỗi điểm ảnh rồi chia trường nhìn.","Đọc lại SOP mục 4.2: thiết bị bảo vệ an toàn chỉ được thay đổi qua đánh giá rủi ro và phê duyệt."],en:["Place the draft configuration next to the inspection spec and re-read the minimum pixel rule.","Apply SOP 3.2: convert defect size into pixel size, then divide the field of view by it.","Re-read SOP 4.2: safeguards may only change through risk assessment and approval."]}},learning:{summary:{vi:"Kỹ sư Robot và Thị giác Máy thiết kế, lập trình và tích hợp robot công nghiệp với hệ thống camera để gắp đặt, lắp ráp, đo kiểm và kiểm tra khuyết tật tự động. Giá trị tạo ra là năng suất cao, chất lượng ổn định và giảm việc nặng nhọc cho con người. Công việc đòi hỏi hiểu động học robot, quang học, xử lý ảnh, hiệu chuẩn và tuân thủ nghiêm ngặt an toàn máy.",en:"A Robotics and Machine Vision Engineer designs, programs and integrates industrial robots with camera systems for automated pick-and-place, assembly, measurement and defect inspection. The value is high throughput, stable quality and less strenuous work for people. The role requires knowledge of robot kinematics, optics, image processing, calibration and strict machine safety compliance."},responsibilities:{vi:["Thiết kế ô robot, chọn robot, tay gắp, camera, ống kính và chiếu sáng phù hợp.","Lập trình quỹ đạo robot, tối ưu chu kỳ và tránh va chạm.","Xây dựng thuật toán xử lý ảnh, hiệu chuẩn camera và hiệu chuẩn tay - mắt.","Đánh giá rủi ro an toàn, cấu hình vùng bảo vệ, cửa khóa liên động và dừng khẩn.","Chạy thử, đo năng lực hệ thống kiểm tra và bàn giao tài liệu vận hành."],en:["Design robot cells and select the robot, gripper, camera, lens and lighting.","Program robot paths, optimise cycle time and avoid collisions.","Build image processing algorithms and calibrate cameras and hand-eye relationships.","Assess safety risks and configure protective zones, interlocked guards and emergency stops.","Commission, measure inspection system capability and hand over operating documents."]},competencies:[{name:{vi:"Lập trình robot",en:"Robot programming"},desc:{vi:"Dạy điểm, lập trình ngoại tuyến, quản lý hệ tọa độ công cụ và phôi.",en:"Teach points, program offline and manage tool and work object frames."}},{name:{vi:"Quang học và chiếu sáng",en:"Optics and lighting"},desc:{vi:"Tính trường nhìn, độ phân giải, độ sâu trường ảnh và chọn kỹ thuật chiếu sáng.",en:"Compute field of view, resolution and depth of field and choose lighting techniques."}},{name:{vi:"Xử lý ảnh",en:"Image processing"},desc:{vi:"Dùng lọc, phân ngưỡng, tìm cạnh, đối sánh mẫu và mô hình học sâu khi cần.",en:"Apply filtering, thresholding, edge finding, pattern matching and deep learning where needed."}},{name:{vi:"An toàn máy",en:"Machine safety"},desc:{vi:"Đánh giá rủi ro, tính khoảng cách an toàn và chọn mức hiệu năng PL cho mạch an toàn.",en:"Assess risk, calculate safety distances and set performance levels for safety circuits."}},{name:{vi:"Tích hợp hệ thống",en:"System integration"},desc:{vi:"Kết nối robot, camera, PLC qua giao tiếp công nghiệp và đồng bộ tín hiệu kích hoạt.",en:"Connect robots, cameras and PLCs over industrial protocols and synchronise triggers."}}],knowledge:{vi:["ISO 10218-1 và ISO 10218-2 về an toàn robot công nghiệp và hệ thống robot.","ISO/TS 15066 về robot cộng tác và giới hạn lực, áp suất tiếp xúc.","ISO 13849-1 về bộ phận liên quan an toàn của hệ thống điều khiển và mức PL.","ISO 13855 về bố trí thiết bị bảo vệ theo tốc độ tiếp cận của cơ thể người.","EMVA 1288 về đặc tính camera và cảm biến ảnh; nguyên lý lấy mẫu và độ phân giải không gian."],en:["ISO 10218-1 and ISO 10218-2 on safety of industrial robots and robot systems.","ISO/TS 15066 on collaborative robots and contact force and pressure limits.","ISO 13849-1 on safety-related parts of control systems and performance levels.","ISO 13855 on positioning safeguards based on human body approach speeds.","EMVA 1288 on camera and image sensor characterisation; sampling and spatial resolution principles."]},tools:["Phần mềm lập trình robot ngoại tuyến","Thư viện xử lý ảnh công nghiệp","Camera công nghiệp và ống kính telecentric","Bộ chiếu sáng vòm, thanh, nền sau","Bảng hiệu chuẩn dạng lưới"],kpis:{vi:["Thời gian chu kỳ trạm so với mục tiêu thiết kế.","Tỷ lệ bỏ sót khuyết tật và tỷ lệ báo lỗi giả của hệ thống thị giác.","Độ sẵn sàng của ô robot.","Số sự cố an toàn hoặc vô hiệu hóa thiết bị bảo vệ (mục tiêu bằng 0)."],en:["Station cycle time versus design target.","Vision system escape rate and false reject rate.","Robot cell availability.","Safety incidents or defeated safeguards (target zero)."]},day:[{time:"08:00",vi:"Xem thống kê lỗi giả và bỏ sót của trạm thị giác ca trước.",en:"Review false rejects and escapes from the vision stations last shift."},{time:"09:30",vi:"Hiệu chuẩn lại camera và tay - mắt sau khi thay ống kính.",en:"Recalibrate the camera and hand-eye relationship after a lens change."},{time:"11:00",vi:"Tối ưu quỹ đạo robot, giảm 0.4 giây chu kỳ mà không vượt giới hạn tốc độ an toàn.",en:"Optimise robot paths to cut 0.4 s of cycle time within safe speed limits."},{time:"14:00",vi:"Kiểm tra vùng quét an toàn, cửa liên động và nút dừng khẩn theo danh mục.",en:"Check safety scanner zones, interlocked doors and emergency stops against the checklist."},{time:"16:30",vi:"Ghi nhận thay đổi thuật toán, sao lưu chương trình robot và cấu hình camera.",en:"Log algorithm changes and back up robot programs and camera configurations."}],mistakes:{vi:["Chọn camera theo nguyên tắc 1 điểm ảnh cho mỗi khuyết tật, dẫn tới bỏ sót lỗi.","Bỏ qua dung sai vị trí khi tính trường nhìn khiến chi tiết lọt ra ngoài ảnh.","Tắt hoặc thu nhỏ vùng an toàn để tăng tốc độ mà không đánh giá rủi ro lại."],en:["Sizing the camera at 1 pixel per defect, causing missed defects.","Ignoring positioning tolerance in the FOV so parts fall outside the image.","Muting or shrinking safety zones for speed without a new risk assessment."]},career:[{vi:"Kỹ thuật viên robot",en:"Robot technician"},{vi:"Kỹ sư robot và thị giác máy",en:"Robotics and machine vision engineer"},{vi:"Kỹ sư trưởng tích hợp hệ thống tự động",en:"Lead automation integration engineer"},{vi:"Trưởng phòng tự động hóa thông minh",en:"Head of smart automation"}],glossary:[{term:"FOV",vi:"Trường nhìn, vùng không gian camera thu được trong một ảnh.",en:"Field of view, the area a camera captures in one image."},{term:"Spatial resolution",vi:"Độ phân giải không gian, kích thước thực tế mà mỗi điểm ảnh biểu diễn (mm/px).",en:"The real-world size each pixel represents (mm/px)."},{term:"Hand-eye calibration",vi:"Hiệu chuẩn quan hệ tọa độ giữa camera và robot để robot gắp đúng vị trí ảnh.",en:"Calibrating the camera-to-robot coordinate relationship so the robot picks where the image shows."},{term:"Telecentric lens",vi:"Ống kính giữ độ phóng đại không đổi theo khoảng cách, phù hợp đo kích thước.",en:"A lens with constant magnification over distance, suited to dimensional measurement."},{term:"Muting",vi:"Tạm vô hiệu hóa chức năng bảo vệ theo điều kiện thiết kế trước; không được dùng tùy tiện.",en:"Temporarily suspending a protective function under pre-designed conditions; never used ad hoc."}],quiz:[{q:{vi:"Trường nhìn 120 mm, khuyết tật nhỏ nhất 0.1 mm, cần 3 điểm ảnh trên khuyết tật. Cần bao nhiêu điểm ảnh ngang?",en:"FOV 120 mm, smallest defect 0.1 mm, 3 pixels needed per defect. How many horizontal pixels?"},options:{vi:["1200","2400","4800","3600"],en:["1200","2400","4800","3600"]},answer:3,explain:{vi:"Mỗi điểm ảnh 0.1 / 3 mm, số điểm ảnh = 120 / (0.1 / 3) = 3600.",en:"Each pixel is 0.1 / 3 mm, so pixels = 120 / (0.1 / 3) = 3600."}},{q:{vi:"Để đo kích thước biên dạng chi tiết chính xác bằng hình bóng, kỹ thuật chiếu sáng nào phù hợp nhất?",en:"Which lighting best suits precise silhouette measurement of a part outline?"},options:{vi:["Chiếu sáng nền sau","Chiếu sáng góc thấp","Đèn vòm khuếch tán","Đèn đồng trục"],en:["Backlight","Low-angle dark-field light","Diffuse dome light","Coaxial light"]},answer:0,explain:{vi:"Nền sau tạo hình bóng tương phản cao, biên chi tiết sắc nét để đo.",en:"A backlight creates a high-contrast silhouette with sharp edges for measurement."}},{q:{vi:"Quản lý yêu cầu tắt cảm biến quét an toàn để robot chạy nhanh khi demo. Bạn làm gì?",en:"A manager asks you to mute the safety scanner so the robot runs fast in a demo. What do you do?"},options:{vi:["Tắt trong lúc demo","Thu nhỏ vùng quét tối đa","Từ chối, kiểm tra cấu hình vùng theo đánh giá rủi ro và báo trưởng nhóm","Dán băng che cảm biến"],en:["Mute it during the demo","Shrink the zone as much as possible","Refuse, check zone settings against the risk assessment and inform the lead","Tape over the sensor"]},answer:2,explain:{vi:"Vô hiệu hóa thiết bị bảo vệ có thể gây chấn thương nghiêm trọng; mọi thay đổi phải qua đánh giá rủi ro.",en:"Defeating safeguards can cause serious injury; any change must go through risk assessment."}},{q:{vi:"Tiêu chuẩn nào quy định giới hạn lực và áp suất tiếp xúc cho robot cộng tác?",en:"Which document sets contact force and pressure limits for collaborative robots?"},options:{vi:["ISO 13855","ISO/TS 15066","ISO 9001","EMVA 1288"],en:["ISO 13855","ISO/TS 15066","ISO 9001","EMVA 1288"]},answer:1,explain:{vi:"ISO/TS 15066 hướng dẫn vận hành cộng tác, gồm giới hạn sinh cơ học khi tiếp xúc.",en:"ISO/TS 15066 guides collaborative operation, including biomechanical contact limits."}}],tools_en:["Offline robot programming software","Industrial image processing library","Industrial camera and telecentric lens","Dome, bar and backlight illumination","Grid calibration target"]}}})})(window.KKR);
